{
  "groups": [
    {
      "group_id": "low_rate_lockin_high_impact",
      "rule": "rate_type == 'fixed' and origination_year >= 2020 and origination_year <= 2021",
      "rationale": "Borrowers who secured historically low rates during the pandemic face the largest potential payment shocks upon renewal."
    },
    {
      "group_id": "vulnerable_high_debt_burden",
      "rule": "n_children >= 2 and household_income_cad < 75000",
      "rationale": "Families with multiple children and lower household incomes have minimal financial buffer to absorb rising living costs and higher mortgage payments."
    },
    {
      "group_id": "stressed_variable_rate",
      "rule": "rate_type == 'variable' and credit_score_band == 'below_600'",
      "rationale": "Borrowers already experiencing variable rate hikes with low credit scores are at high risk of payment default and have limited refinancing options."
    },
    {
      "group_id": "equity_rich_uninsured",
      "rule": "insured_flag == False and credit_score_band == '720_plus'",
      "rationale": "High-credit, uninsured borrowers have the most mobility and leverage to switch lenders if offered better retention pricing."
    },
    {
      "group_id": "life_event_impacted",
      "rule": "life_event_6m == True and life_event_type != 'none'",
      "rationale": "Borrowers undergoing significant life changes are prone to reassessing their long-term financial obligations and housing needs."
    },
    {
      "group_id": "liquidity_constrained_renters",
      "rule": "occupancy_type == 'rental' and has_savings == False",
      "rationale": "Investment property owners without cash reserves are highly sensitive to negative cash flow caused by rising interest rates."
    }
  ]
}
